import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    ids = {}
    outd, ind = [], []
    parent = []

    def node(key):
        if key not in ids:
            ids[key] = len(ids)
            outd.append(0)
            ind.append(0)
            parent.append(len(parent))
        return ids[key]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for w in words:
        a = node(w[:3])
        b = node(w[-3:])
        outd[a] += 1
        ind[b] += 1
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    starts = ends = 0
    ok = True
    for v in range(len(ids)):
        d = outd[v] - ind[v]
        if d == 1:
            starts += 1
        elif d == -1:
            ends += 1
        elif d != 0:
            ok = False
    if starts > 1 or ends > 1:
        ok = False
    if ok:
        roots = {find(v) for v in range(len(ids))}
        ok = len(roots) == 1
    print('true' if ok else 'false')


